import json, sys

data = json.load(sys.stdin)

# Group by repo
repos = {}
for ev in data:
    repo = ev['repo']['name']
    if repo not in repos:
        repos[repo] = {'pushes': [], 'prs': [], 'reviews': [], 'comments': [], 'creates': []}

    t = ev['type']
    p = ev['payload']

    if t == 'PushEvent':
        commits = p.get('commits', [])
        for c in commits:
            msg = c.get('message', '')
            if not msg.startswith('Merge'):
                repos[repo]['pushes'].append(msg.split('\n')[0])

    elif t == 'PullRequestEvent':
        pr = p.get('pull_request', {})
        repos[repo]['prs'].append({
            'action': p.get('action'),
            'number': pr.get('number'),
            'title': pr.get('title'),
            'url': pr.get('html_url'),
            'merged': pr.get('merged', False)
        })

    elif t == 'PullRequestReviewEvent':
        pr = p.get('pull_request', {})
        review = p.get('review', {})
        body = review.get('body') or ''
        if len(body.strip()) > 10:  # substantive
            repos[repo]['reviews'].append({
                'title': pr.get('title'),
                'url': pr.get('html_url'),
                'number': pr.get('number')
            })

    elif t == 'IssueCommentEvent':
        issue = p.get('issue', {})
        comment = p.get('comment', {})
        body = comment.get('body') or ''
        if len(body.strip()) > 20:
            repos[repo]['comments'].append({
                'title': issue.get('title'),
                'url': issue.get('html_url'),
                'number': issue.get('number')
            })

    elif t == 'CreateEvent':
        if p.get('ref_type') == 'tag':
            repos[repo]['creates'].append(p.get('ref'))

# Print summary
for repo, activity in repos.items():
    total_commits = len(activity['pushes'])
    total_prs = len(activity['prs'])
    print(f'=== {repo} ===')
    print(f'  Commits ({total_commits}): {activity[\"pushes\"][:5]}')
    print(f'  PRs ({total_prs}): {[(p[\"action\"], p[\"number\"], p[\"title\"][:60], p[\"merged\"]) for p in activity[\"prs\"]]}')
    print(f'  Reviews ({len(activity[\"reviews\"])}): {[(r[\"number\"], r[\"title\"][:60]) for r in activity[\"reviews\"]]}')
    print(f'  Comments ({len(activity[\"comments\"])}): {[(c[\"number\"], c[\"title\"][:50]) for c in activity[\"comments\"]]}')
    print()
"

